import type {
  GeneratorOptions,
  GeneratedProject,
  Diagnostic,
  Operation,
} from "./model.js";
import { parseDocument, normalize } from "./parse.js";
import { createSchemaWriter } from "./schema.js";
import { RUNTIME_SOURCE, HOOKS_SOURCE, RUNTIME_LICENSE } from "./templates.js";
export type {
  GeneratorOptions,
  GeneratedProject,
  Diagnostic,
  Operation,
} from "./model.js";
export { MAX_BYTES, MAX_OPERATIONS } from "./model.js";
export { parseConfig, DEFAULT_CONFIG } from "./config.js";
export type { ChainSpecConfig } from "./config.js";
export { fetchDocument } from "./source.js";
export const VERSION = "2.1.0";
const q = JSON.stringify;
const banner =
  "// Generated by ChainSpec. Do not edit; regenerate from your OpenAPI document.\n";
export function generateSDK(
  input: string | Record<string, any>,
  options: GeneratorOptions = {},
): GeneratedProject {
  const doc = parseDocument(input);
  const diagnostics: Diagnostic[] = [];
  const { namespace, operations, baseUrl } = normalize(
    doc,
    options,
    diagnostics,
  );
  const writer = createSchemaWriter(doc, diagnostics);
  const schemaCount = Object.keys(writer.registry).length;
  if (schemaCount > 5000) throw new Error("最多5000个模型");
  let types = banner;
  for (const [name, direction] of [
    ["Schemas", "neutral"],
    ["InputSchemas", "input"],
    ["OutputSchemas", "output"],
  ] as const) {
    types += `export interface ${name} {\n`;
    for (const key of Object.keys(writer.registry).sort())
      types += `  ${q(key)}: ${writer.type(writer.registry[key], direction, key)};\n`;
    types += "}\n\n";
  }
  types += "export interface Operations {\n";
  for (const op of operations) {
    const fields: string[] = [];
    for (const loc of ["path", "query", "cookie"] as const) {
      const ps = op.parameters.filter((p) => p.in === loc);
      if (!ps.length) continue;
      const field = loc === "cookie" ? "cookies" : loc;
      fields.push(
        `${field}${ps.some((p) => p.required) ? "" : "?"}: { ${ps.map((p) => `${q(p.name)}${p.required ? "" : "?"}: ${writer.type(p.schema, "input", op.id + "." + loc + "." + p.name)};`).join(" ")} };`,
      );
    }
    const body = op.body
      ? writer.type(op.body.schema, "input", op.id + ".body")
      : "never";
    const headerParams = op.parameters.filter((p) => p.in === "header");
    const headers = `{ ${headerParams.map((p) => `${q(p.name)}${p.required ? "" : "?"}: ${writer.type(p.schema, "input", op.id + ".header." + p.name)};`).join(" ")} }`;
    types += `  ${q(op.id)}: { params: ${fields.length ? `{ ${fields.join(" ")} }` : "Record<string, never>"}; body: ${body}; headers: ${headers}; output: ${writer.type(op.response, "output", op.id + ".response")}; };\n`;
  }
  types += "}\n";
  const groups = new Map<string, Operation[]>();
  for (const op of operations) {
    if (!groups.has(op.controller)) groups.set(op.controller, []);
    groups.get(op.controller)!.push(op);
  }
  const index = (id: string, field: "params" | "body" | "output") =>
    `Operations[${q(id)}][${q(field)}]`;
  function client(react: boolean) {
    let text =
      banner +
      `import {createClient,type ClientConfig,type Endpoint} from './runtime.js';\nimport type {Operations} from './types.js';\n`;
    if (react)
      text += `import {withQuery,withMutation,type QueryEndpoint,type MutationEndpoint} from './hooks.js';\n`;
    const typeName = react ? "ReactAPI" : "API";
    text += `\nexport interface ${typeName} { ${q(namespace)}: {\n`;
    for (const [group, ops] of groups) {
      text += `  ${q(group)}: {\n`;
      for (const op of ops) {
        const ep = react
          ? op.method === "GET" || op.method === "HEAD"
            ? "QueryEndpoint"
            : "MutationEndpoint"
          : "Endpoint";
        text += `${op.deprecated ? "/** @deprecated */\n" : ""}    ${q(op.name)}: ${ep}<${index(op.id, "params")},${index(op.id, "body")},${index(op.id, "output")},${Boolean(op.body)},${op.body?.required ?? false}>;\n`;
      }
      text += "  };\n";
    }
    text += "}; }\n";
    text += `export function ${react ? "createReactAPI" : "createAPI"}(config:ClientConfig={}):${typeName} {\n const client=createClient({...config,baseUrl:config.baseUrl??${q(baseUrl)}});\n return {${q(namespace)}: {\n`;
    for (const [group, ops] of groups) {
      text += `${q(group)}: {\n`;
      for (const op of ops) {
        const definition = {
          id: op.id,
          method: op.method,
          path: op.path,
          controller: op.controller,
          name: op.name,
          parameters: op.parameters.map(({ schema, ...p }) => p),
          hasBody: Boolean(op.body),
          bodyRequired: op.body?.required,
          mediaType: op.body?.mediaType,
          responseType: op.responseType,
        };
        let endpoint = `client.endpoint<${index(op.id, "params")},${index(op.id, "body")},${index(op.id, "output")},${Boolean(op.body)},${op.body?.required ?? false}>(${q(definition)})`;
        if (react)
          endpoint = `${op.method === "GET" || op.method === "HEAD" ? "withQuery" : "withMutation"}(${endpoint})`;
        text += `${q(op.name)}: ${endpoint},\n`;
      }
      text += "},\n";
    }
    return text + "}};\n}\n";
  }
  const files: Record<string, string> = {
    "LICENSE.runtime.txt": RUNTIME_LICENSE,
    "types.ts": types,
    "runtime.ts": RUNTIME_SOURCE,
    "client.ts": client(false),
    "index.ts": `export {createAPI,type API} from './client.js';\nexport {ApiError,defaultRequest} from './runtime.js';\nexport type {ClientConfig,RequestContext,TransportResponse,RequestAdapter,RequestOptions,Endpoint} from './runtime.js';\nexport type {Schemas,InputSchemas,OutputSchemas,Operations} from './types.js';\n`,
  };
  if (options.hooks !== false) {
    files["hooks.ts"] = HOOKS_SOURCE;
    files["react.ts"] =
      client(true) +
      `\nexport type {QueryOptions,MutationOptions} from './hooks.js';\n`;
  }
  files["manifest.json"] = JSON.stringify(
    {
      generator: "ChainSpec",
      version: VERSION,
      namespace,
      baseUrl,
      operations: operations.map(({ response, parameters, body, ...op }) => ({
        ...op,
        parameters: parameters.map(({ schema, ...p }) => p),
        body: body
          ? { mediaType: body.mediaType, required: body.required }
          : undefined,
      })),
      diagnostics,
    },
    null,
    2,
  );
  const first = operations.find((o) => o.method === "GET") ?? operations[0];
  const access = `API.${namespace}[${q(first.controller)}][${q(first.name)}]`;
  files["README.md"] =
    `# Generated SDK\n\nGenerated locally with ChainSpec ${VERSION}. Copy these files into your TypeScript project. No runtime code evaluation or request is performed by the generator.\n\n## Setup\n\nNode22+ or a browser with Fetch, Headers, FormData, Blob. TypeScript moduleResolution Bundler or NodeNext; .js imports resolve to the corresponding .ts sources.\n\nPlain SDK: import {createAPI} from './index.js'. No React/SWR dependency.\n\n${options.hooks === false ? "" : "React SDK: npm install swr@^2.5.1 react@^19.3.1, then import {createReactAPI} from './react.js'. Use the returned API as a module-level singleton (or memoize it per Provider/SSR request). Do not create clients on every render.\n\n"}## Calls\n\n\`\`\`ts\nimport {createAPI} from './index.js';\nconst API=createAPI({baseUrl:${q(baseUrl)},cacheScope:()=> 'tenant:user:auth-revision'});\n// Inspect generated Operations params/body before calling:\n// ${access}.request(params${first.body ? ", body" : ""}, options);\n\`\`\`\n\n.request() returns the documented response body. The first params object contains path/query/cookies. With a documented request body: request(params, body, options). Without one: request(params?, options). Headers are options.headers (standard HeadersInit) and may also be set globally or by beforeRequest. Empty params are {} when a body is present. Operations exposes params/body/headers/output types. Required arguments are required in TypeScript and checked for presence by the default runtime. Schema validation is NOT performed. Missing response schemas are unknown. JS numbers can lose int64 precision: ask your server for strings if required.\n\nGET/HEAD .useRequest(params, {enabled,headers,signal,swr}) reads with SWR; null params or enabled:false pauses it. If a query operation documents a body, use the same three positions as request. Other methods .useRequest(params, body, {headers,signal,swr}) (also .useMutation) bind params and an optional body, never send automatically. trigger() uses the bound body; trigger(body) supplies or overrides it. If a required body was not bound, TypeScript requires trigger(body). For operations without a body use .useRequest(params, options) then trigger(). Trigger options, such as throwOnError, are its second argument. Hook options are flat: headers/signal/interceptors are alongside swr, not under request. Hooks must be called unconditionally at React component/custom-hook top level. HEAD returns no body in Fetch.\n\nCache keys isolate client instances, base URL, operation, inputs, request headers and cacheScope. Change cacheScope after switching users/tenants or changing authorization within one client. Do not put tokens in cacheScope. Logout should also clear your SWR Provider cache. Request interceptors do not automatically change cache keys.\n\n## Extension points\n\n- request: async context => ({data,status,headers:new Headers()}) replaces the entire Fetch transport. context includes URL, method, headers, structured body, mediaType, operation and AbortSignal. Custom adapters must preserve the declared response shape; returning an Axios response unchanged is NOT compatible (normalize response.headers).\n- beforeRequest: async context => context (or void); global handlers run before per-call handlers. Add auth headers, tracing, or cancellation here.\n- afterResponse: async (response,context) => response (or void), for successful responses only. Unwrapping changes the schema contract; do not unwrap unless the server schema already describes the unwrapped body.\n- onError: async (error,context) => void; errors are rethrown. Non-2xx status becomes ApiError with status/data/headers. Network and AbortError are preserved. No automatic retry in .request(). SWR has its own configurable retries.\n\nSupported query serialization: form (arrays and flat objects), spaceDelimited, pipeDelimited, flat deepObject. Path/header simple serialization; header objects and nested query objects need a custom serializer. Cookie parameters require a custom Node request adapter (Fetch in browsers cannot set Cookie headers). JSON, flat multipart and URL-encoded bodies supported; nested forms need a custom adapter. JSON-schema constraints, auth schemes, oneOf exclusivity, server variables, parameter serialization and streaming may need application validation.\n\nThe generator supports local refs, not remote refs. Review manifest.json diagnostics, media choices and operation names. Do not add this SDK or its spec to a public repository without checking that disclosure is intended.\n`;
  diagnostics.push({
    level: "info",
    code: "static-types",
    message: "类型用于编译期；不执行Schema运行时验证，也不自动配置鉴权。",
  });
  // Keep the final diagnostic in the downloadable manifest as well.
  const manifest = JSON.parse(files["manifest.json"]);
  manifest.diagnostics = diagnostics;
  files["manifest.json"] = JSON.stringify(manifest, null, 2);
  return {
    title:
      typeof doc.info?.title === "string" ? doc.info.title : "Untitled API",
    version: String(doc.info?.version ?? ""),
    namespace,
    baseUrl,
    operations,
    schemaCount,
    diagnostics,
    files,
  };
}
